def max_score_difference(N, cards):
    if N % 2 == 0:
        return sum(cards[::2]) - sum(cards[1::2])
    else:
        return max(sum(cards[:i]) - sum(cards[i:]) for i in range(1, N+1))

import sys
input = sys.stdin.read
data = input().split()
N = int(data[0])
cards = list(map(int, data[1:]))

print(max_score_difference(N, cards))
